package com.sahyadri.sahyadripooltrip.service;
import com.sahyadri.sahyadripooltrip.entity.NatureDestination; import com.sahyadri.sahyadripooltrip.repository.NatureDestinationRepository; import org.springframework.stereotype.Service; import java.util.List; import java.util.Optional;
@Service public class NatureDestinationService{private final NatureDestinationRepository repo; public NatureDestinationService(NatureDestinationRepository r){repo=r;} public List<NatureDestination> all(){return repo.findAll();} public long count(){return repo.count();} public Optional<NatureDestination> byId(String id){return repo.findById(id);} public List<NatureDestination> section(String s){return repo.findBySectionIgnoreCase(s);} public List<NatureDestination> state(String s){return repo.findByStateIgnoreCase(s);} public List<NatureDestination> category(String s){return repo.findByCategoryIgnoreCase(s);} public List<NatureDestination> sectionState(String a,String b){return repo.findBySectionIgnoreCaseAndStateIgnoreCase(a,b);}}
